import XCTest

// Pins the Swift port to the Python reference it was ported from.
//
// `SwingDetector.swift` is a hand port of `iphone/swing_metrics.py`. The Python
// has 93 tests; until this file existed, the Swift had none, and its
// faithfulness rested entirely on careful reading. Reading found four real
// bugs — which is exactly why it should not be trusted to find the fifth.
//
// `swing_vectors.json` is generated by running the Python reference over a set
// of deliberately awkward motion traces and recording what it actually
// produces. These tests replay the same inputs through the Swift and assert the
// same outputs. A failure here means the watch and the phone would report
// different numbers for the same swing.
//
// The fixture pins what the reference DOES, not what it ought to do. If you
// decide the reference is wrong, change the Python, change its tests, then
// regenerate — do not "fix" the expectation here.
//
//   python3 iphone/gen_swing_vectors.py          # regenerate
//   python3 iphone/gen_swing_vectors.py --check  # is the committed copy stale?
//
// SETUP (see WATCH.md): this belongs in a watchOS Unit Testing Bundle target.
// Add `SwingDetector.swift` to that target's Compile Sources, and
// `swing_vectors.json` to its Copy Bundle Resources. No @testable import is
// needed that way, which keeps this independent of how Xcode names the module.

final class SwingDetectorTests: XCTestCase {

    // MARK: - Fixture loading

    private static let fixture: [String: Any] = {
        let bundle = Bundle(for: SwingDetectorTests.self)
        guard let url = bundle.url(forResource: "swing_vectors", withExtension: "json") else {
            fatalError("""
                swing_vectors.json is not in the test bundle.
                Add it to the test target's Build Phases → Copy Bundle Resources.
                """)
        }
        guard let data = try? Data(contentsOf: url),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        else {
            fatalError("swing_vectors.json could not be parsed")
        }
        return json
    }()

    private func section(_ key: String) -> [[String: Any]] {
        guard let rows = Self.fixture[key] as? [[String: Any]] else {
            XCTFail("fixture section '\(key)' missing or malformed")
            return []
        }
        return rows
    }

    /// Decodes the fixture's `[[t, mag, [r,p,y] | null], ...]` sample rows.
    private func samples(_ raw: Any?) -> [MotionSample] {
        guard let rows = raw as? [[Any]] else {
            XCTFail("malformed samples")
            return []
        }
        return rows.compactMap { row in
            guard row.count >= 2,
                  let t = (row[0] as? NSNumber)?.doubleValue,
                  let mag = (row[1] as? NSNumber)?.doubleValue
            else { return nil }
            var attitude: (roll: Double, pitch: Double, yaw: Double)?
            if row.count > 2, let a = row[2] as? [NSNumber], a.count == 3 {
                attitude = (a[0].doubleValue, a[1].doubleValue, a[2].doubleValue)
            }
            return MotionSample(t: t, mag: mag, attitude: attitude)
        }
    }

    /// JSON null arrives as NSNull, so an optional Double needs unwrapping that
    /// distinguishes "absent" from "present and null".
    private func optionalDouble(_ value: Any?) -> Double? {
        guard let number = value as? NSNumber, !(value is NSNull) else { return nil }
        return number.doubleValue
    }

    private func optionalInt(_ value: Any?) -> Int? {
        guard let number = value as? NSNumber, !(value is NSNull) else { return nil }
        return number.intValue
    }

    private func optionalString(_ value: Any?) -> String? {
        value as? String
    }

    /// The generator encodes non-finite floats as {"__float__": "inf"|"nan"},
    /// because JSON has no literal for them and every language disagrees about
    /// what to emit instead.
    private func double(_ value: Any?) -> Double? {
        if let sentinel = value as? [String: String], let kind = sentinel["__float__"] {
            switch kind {
            case "inf": return .infinity
            case "-inf": return -.infinity
            case "nan": return .nan
            default: return nil
            }
        }
        return optionalDouble(value)
    }

    // MARK: - Constants

    func testConstantsMatchTheReference() {
        guard let c = Self.fixture["constants"] as? [String: Any] else {
            return XCTFail("constants missing")
        }
        XCTAssertEqual(SwingAnalysis.quietG, optionalDouble(c["quietG"]), "QUIET_G")
        XCTAssertEqual(SwingAnalysis.maxBackswingS, optionalDouble(c["maxBackswingS"]), "MAX_BACKSWING_S")
        XCTAssertEqual(SwingAnalysis.quietRunS, optionalDouble(c["quietRunS"]), "QUIET_RUN_S")
        XCTAssertEqual(TempoBench.tour, optionalDouble(c["tourTempo"]), "TOUR_TEMPO")
        XCTAssertEqual(TempoBench.fps, optionalDouble(c["tourTempoFps"]), "TOUR_TEMPO_FPS")
    }

    // MARK: - Phase detection

    func testFindMotionStart() {
        for row in section("motionStart") {
            let name = row["name"] as? String ?? "?"
            let s = samples(row["samples"])
            guard let peak = optionalInt(row["peak"]) else {
                XCTFail("\(name): no peak"); continue
            }
            let expected = optionalInt(row["expect"])
            let actual = SwingAnalysis.findMotionStart(s, peak: peak)
            XCTAssertEqual(actual, expected, """
                findMotionStart diverged from the Python reference.
                  case:     \(name)
                  expected: \(expected.map(String.init) ?? "nil")
                  actual:   \(actual.map(String.init) ?? "nil")
                An off-by-one here silently changes every tempo reading.
                """)
        }
    }

    func testFindTransition() {
        for row in section("transition") {
            let name = row["name"] as? String ?? "?"
            let s = samples(row["samples"])
            guard let peak = optionalInt(row["peak"]) else {
                XCTFail("\(name): no peak"); continue
            }
            let expected = optionalInt(row["expect"])
            // The reference derives `start` itself; a nil start means the
            // transition is unresolvable, which is the honest answer.
            guard let start = optionalInt(row["start"]) else {
                XCTAssertNil(expected, "\(name): reference resolved a transition without a start")
                continue
            }
            let actual = SwingAnalysis.findTransition(s, peak: peak, start: start)
            XCTAssertEqual(actual, expected, """
                findTransition diverged.
                  case:     \(name)  (start=\(start), peak=\(peak))
                  expected: \(expected.map(String.init) ?? "nil")
                  actual:   \(actual.map(String.init) ?? "nil")
                """)
        }
    }

    // MARK: - Full analysis

    func testAnalyse() {
        for row in section("analyse") {
            let name = row["name"] as? String ?? "?"
            let s = samples(row["samples"])
            guard let peak = optionalInt(row["peak"]),
                  let expect = row["expect"] as? [String: Any]
            else { XCTFail("\(name): malformed case"); continue }

            let m = SwingAnalysis.analyse(s, peak: peak)

            assertEqual(m.peakG, optionalDouble(expect["peak_g"]), "\(name): peak_g")
            assertEqual(m.backswingS, optionalDouble(expect["backswing_s"]), "\(name): backswing_s")
            assertEqual(m.downswingS, optionalDouble(expect["downswing_s"]), "\(name): downswing_s")
            assertEqual(m.tempoRatio, optionalDouble(expect["tempo_ratio"]), "\(name): tempo_ratio")
            assertEqual(m.yawSweepDeg, optionalDouble(expect["yaw_deg"]), "\(name): yaw_deg")

            XCTAssertEqual(m.tempoFrames, optionalString(expect["tempo_frames"]), """
                \(name): tempo_frames diverged.
                  expected: \(optionalString(expect["tempo_frames"]) ?? "nil")
                  actual:   \(m.tempoFrames ?? "nil")
                """)
        }
    }

    /// The no-address case is the one that matters most: it must produce nil,
    /// not a fabricated tempo. A 0.06 s backswing against a 1.9 s downswing
    /// looks like data and poisons the round's statistics without ever tripping
    /// a missing-data warning.
    func testNoAddressProducesNoTempoRatherThanANonsenseOne() {
        let matches = section("analyse").filter {
            (($0["expect"] as? [String: Any])?["tempo_ratio"] as? NSNumber) == nil
                && ($0["expect"] as? [String: Any])?["tempo_ratio"] is NSNull
        }
        XCTAssertFalse(matches.isEmpty, "fixture no longer covers the no-address case")
        for row in matches {
            let m = SwingAnalysis.analyse(samples(row["samples"]),
                                          peak: optionalInt(row["peak"]) ?? 0)
            XCTAssertNil(m.tempoRatio, "\(row["name"] ?? "?"): fabricated a tempo")
            XCTAssertNil(m.backswingS)
            XCTAssertNil(m.downswingS)
            XCTAssertGreaterThan(m.peakG, 0, "peak_g should still be reported")
        }
    }

    // MARK: - Tour Tempo frames

    /// Includes the exact .5 frame boundaries. These are not academic: a 0.75 s
    /// backswing sits dead centre of the elite 0.7-0.9 s range, and 0.75 x 30 is
    /// exactly 22.5 frames. Python's formatter rounds half-to-even (22); Swift's
    /// `.rounded()` rounds half-away-from-zero (23) unless told otherwise. That
    /// is one swing reported two different ways.
    func testTempoFrames() {
        for row in section("frames") {
            let b = optionalDouble(row["backswing_s"])
            let d = optionalDouble(row["downswing_s"])
            let expected = optionalString(row["expect"])
            let actual = TempoBench.frames(b, d)
            XCTAssertEqual(actual, expected, """
                tempo frames diverged at a rounding boundary.
                  backswing: \(b.map(String.init) ?? "nil")
                  downswing: \(d.map(String.init) ?? "nil")
                  expected:  \(expected ?? "nil")
                  actual:    \(actual ?? "nil")
                Python rounds half-to-even; use .rounded(.toNearestOrEven).
                """)
        }
    }

    func testTempoVerdict() {
        for row in section("verdict") {
            let ratio = double(row["ratio"])
            let expected = optionalString(row["expect"]) ?? ""
            XCTAssertEqual(TempoBench.verdict(ratio), expected,
                           "verdict diverged for ratio \(ratio.map(String.init) ?? "nil")")
        }
    }

    // MARK: - Adaptive threshold

    /// Steps the detector one observation at a time and compares baseline,
    /// threshold and readiness at every step, so a divergence is localised to
    /// the sample that caused it rather than showing up as a wrong verdict
    /// hundreds of samples later.
    func testAdaptiveThreshold() {
        for row in section("threshold") {
            let name = row["name"] as? String ?? "?"
            guard let observations = row["observations"] as? [NSNumber],
                  let trace = row["trace"] as? [[String: Any]],
                  let config = row["init"] as? [String: Any]
            else { XCTFail("\(name): malformed case"); continue }

            let detector = AdaptiveThreshold(
                windowSeconds: optionalDouble(config["window_seconds"]) ?? 10,
                ratio: optionalDouble(config["ratio"]) ?? 2.0,
                floorG: optionalDouble(config["floor_g"]) ?? 1.5,
                sampleHz: optionalDouble(config["sample_hz"]) ?? 100,
                recomputeEvery: optionalInt(config["recompute_every"]) ?? 25
            )

            XCTAssertEqual(observations.count, trace.count, "\(name): trace length")
            for (i, observation) in observations.enumerated() where i < trace.count {
                detector.observe(observation.doubleValue)
                let step = trace[i]
                assertEqual(detector.baseline(), optionalDouble(step["baseline"]),
                            "\(name): baseline at step \(i)")
                assertEqual(detector.threshold(), optionalDouble(step["threshold"]),
                            "\(name): threshold at step \(i)")
                XCTAssertEqual(detector.isReady, step["ready"] as? Bool,
                               "\(name): ready at step \(i)")
            }

            for probe in (row["probes"] as? [[String: Any]] ?? []) {
                guard let mag = optionalDouble(probe["mag"]),
                      let expected = probe["expect"] as? Bool else { continue }
                XCTAssertEqual(detector.isSwing(mag), expected,
                               "\(name): isSwing(\(mag))")
            }
        }
    }

    // MARK: - Shot distance

    /// The watch now measures shots itself rather than only recording where you
    /// stood, so the geodesy runs in two languages and has to agree. The poles,
    /// the antimeridian and identical points are included because those are
    /// where a hand-ported haversine goes wrong.
    ///
    /// NOTE: add `SessionModel.swift` to the test target for this section, or
    /// delete it — the rest of the file only needs `SwingDetector.swift`.
    func testHaversineMatchesTheReference() {
        for row in section("shotDistance") {
            guard let from = row["from"] as? [NSNumber],
                  let to = row["to"] as? [NSNumber],
                  let expected = optionalDouble(row["expect_m"])
            else { continue }   // the annotation-pass row has no from/to
            let actual = SessionModel.haversineMetres(
                from[0].doubleValue, from[1].doubleValue,
                to[0].doubleValue, to[1].doubleValue
            )
            XCTAssertEqual(actual, expected, accuracy: 0.01, """
                haversine diverged from the Python reference.
                  case:     \(row["name"] as? String ?? "?")
                  expected: \(expected) m
                  actual:   \(actual) m
                """)
        }
    }

    func testYardConversionMatchesTheReference() {
        for row in section("shotDistance") {
            guard let from = row["from"] as? [NSNumber],
                  let to = row["to"] as? [NSNumber],
                  let expected = optionalDouble(row["expect_yd"])
            else { continue }
            let metres = SessionModel.haversineMetres(
                from[0].doubleValue, from[1].doubleValue,
                to[0].doubleValue, to[1].doubleValue
            )
            XCTAssertEqual(metres / 0.9144, expected, accuracy: 0.01,
                           "yard conversion diverged")
        }
    }

    // MARK: - Sanity

    func testMagnitudeMatchesEuclideanNorm() {
        XCTAssertEqual(SwingAnalysis.magnitude(x: 3, y: 4, z: 0), 5, accuracy: 1e-12)
        XCTAssertEqual(SwingAnalysis.magnitude(x: 0, y: 0, z: 0), 0, accuracy: 1e-12)
        XCTAssertEqual(SwingAnalysis.magnitude(x: -1, y: -2, z: -2), 3, accuracy: 1e-12)
    }

    func testFixtureIsSubstantial() {
        // Guards against a truncated or half-written fixture silently making
        // every test above vacuous.
        XCTAssertGreaterThanOrEqual(section("motionStart").count, 8)
        XCTAssertGreaterThanOrEqual(section("analyse").count, 6)
        XCTAssertGreaterThanOrEqual(section("frames").count, 10)
        XCTAssertGreaterThanOrEqual(section("threshold").count, 6)
    }

    // MARK: - Helpers

    /// Compares optional Doubles with a tolerance far tighter than any value the
    /// reference rounds to, so a genuine divergence cannot hide inside it, while
    /// last-bit float noise from JSON round-tripping does not fail the build.
    private func assertEqual(_ actual: Double?, _ expected: Double?, _ message: String,
                             file: StaticString = #filePath, line: UInt = #line) {
        switch (actual, expected) {
        case (nil, nil):
            break
        case let (a?, e?):
            XCTAssertEqual(a, e, accuracy: 1e-9,
                           "\(message): expected \(e), got \(a)", file: file, line: line)
        case let (a, e):
            XCTFail("\(message): expected \(e.map(String.init) ?? "nil"), got \(a.map(String.init) ?? "nil")",
                    file: file, line: line)
        }
    }
}
